resolve_future_once:
def resolve_future_once(loop, future, *, result=None, exception=None):
    if future is None:
        return

    def resolve():
        if future.done():
            return
        if exception:
            future.set_exception(exception)
        else:
            future.set_result(result)
    loop.call_soon_threadsafe(resolve)

